func:
const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !nw.attributes || !Array.isArray(nw.attributes.lista)) return null;

const lista = nw.attributes.lista;
const fn = nw.attributes.friendly_name || "";
const imie = fn.includes(': ') ? fn.split(': ').pop() : "Uczeń";
const sygnatura = item => `${item.data}_${item.przedmiot}_${item.typ}`;

// Pamięć osobno dla każdej encji (kilkoro dzieci w jednym węźle).
const pamiec = context.get('terminarz_sigs') || {};
let widziane = pamiec[nw.entity_id];
pamiec[nw.entity_id] = lista.map(sygnatura);
context.set('terminarz_sigs', pamiec);

if (widziane === undefined) {
    // Brak pamięci (pierwsze uruchomienie, restart Node-RED): porównujemy z poprzednim stanem.
    if (!ow || !ow.attributes || !Array.isArray(ow.attributes.lista)) return null;
    widziane = ow.attributes.lista.map(sygnatura);
}

const typySprawdzianow = ['Sprawdzian', 'Kartkówka', 'Klasówka'];
const prefiksId = "vultron_term_" + nw.entity_id.replace(/^sensor\.vultron_terminarz_/, '') + "_";
const noweWpisy = lista
    .filter(item => !widziane.includes(sygnatura(item)))
    .map(item => {
        const ikona = typySprawdzianow.includes(item.typ) ? '📝' : '🏠';
        return {
            payload: {
                title: `${ikona} ${item.typ}: ${item.przedmiot}`,
                message: `### ${imie}\n**Termin:** ${item.data}\n**Opis:** ${item.opis}\n\n---\n**Autor:** ${item.autor}`,
                notification_id: (prefiksId + sygnatura(item)).replace(/[^a-z0-9]/gi, '_')
            }
        };
    });

if (noweWpisy.length > 0) return [noweWpisy];
return null;
